<script setup lang="ts">
import {computed,ref,onMounted,onBeforeUnmount} from 'vue'
import {useRouter} from 'vue-router'
import AgentIcon from '@/components/assistant/AgentIcon.vue'
import cropImage from '@/assets/postharvest/crop-products-v1.png'
import {useWorkspaceStore} from '@/stores/workspace'
import {fetchOperations,type OperationRecord} from '@/api/dashboard'
import CropVisionWorkbench from '@/components/workspace/CropVisionWorkbench.vue'
import ObservationHistory from '@/components/workspace/ObservationHistory.vue'
import OperationJournal from '@/components/workspace/OperationJournal.vue'
import PostHarvestCenter from '@/components/workspace/PostHarvestCenter.vue'
const router=useRouter(),store=useWorkspaceStore(),category=ref('all'),tab=ref('overview'),error=ref(''),records=ref<OperationRecord[]>([]),postharvest=ref(false)
const categories=[{id:'pear',name:'泊头鸭梨',position:'0% 0%'},{id:'vegetable',name:'设施蔬菜',position:'100% 100%'},{id:'wheat',name:'旱碱麦',position:'0% 100%'},{id:'jujube',name:'金丝小枣',position:'100% 0%'}]
const tabs=[{id:'overview',name:'总览'},{id:'growth',name:'生长监测'},{id:'vision',name:'病虫害识别'},{id:'yield',name:'产量评估'},{id:'agronomy',name:'农事管理'}]
const cropKey=(crop:string)=>crop.includes('梨')?'pear':crop.includes('枣')?'jujube':crop.includes('麦')?'wheat':'vegetable'
const snapshot=computed(()=>store.snapshot)
const cards=computed(()=>categories.map(c=>{const zones=snapshot.value?.zones.filter(z=>cropKey(z.crop)===c.id)||[];const ids=zones.map(z=>z.entityId);const entities=snapshot.value?.entities.filter(e=>ids.includes(e.id))||[];const batches=records.value.filter(r=>r.kind==='BATCH'&&ids.includes(r.entityId));const amounts:Record<string,number>={};for(const b of batches)amounts[b.unit||'未登记单位']=(amounts[b.unit||'未登记单位']||0)+(b.quantity||0);return {...c,zones,area:zones.map(z=>parseFloat(z.area)).reduce((s,n)=>s+(Number.isFinite(n)?n:0),0),health:entities.filter(e=>e.health!=null).length?Math.round(entities.reduce((s,e)=>s+(e.health||0),0)/entities.filter(e=>e.health!=null).length):null,alerts:snapshot.value?.alerts.filter(a=>ids.includes(a.entityId||'')&&!['已处理','已恢复'].includes(a.status)).length||0,harvest:Object.entries(amounts).map(([u,n])=>n.toLocaleString('zh-CN')+' '+u).join(' / ')||'未登记',batchCount:batches.length}}))
const visible=computed(()=>cards.value.filter(c=>category.value==='all'||c.id===category.value))
const activeCrop=computed(()=>cards.value.find(c=>c.id===category.value)||cards.value[0])
const names=computed(()=>Object.fromEntries((snapshot.value?.entities||[]).map(e=>[e.id,e.name])))
const tasks=computed(()=>records.value.filter(r=>['AGRONOMY','GROWTH'].includes(r.kind)).filter(r=>category.value==='all'||activeCrop.value.zones.some(z=>z.entityId===r.entityId)).slice(0,4))
const riskCount=computed(()=>snapshot.value?.alerts.filter(a=>!['已处理','已恢复'].includes(a.status)).length||0)
function selectCrop(id:string){category.value=id;tab.value='overview'}
function ask(){router.push({path:'/assistant',query:{prompt:`分析${category.value==='all'?'当前农场':activeCrop.value.name}的生长、视觉和农事记录，检索资料，列出依据与缺失条件，不编造产量或病害概率。`,farmId:'yantian-01'}})}
let timer=0,disposed=false
async function refresh(){try{await store.loadDashboard(false,'yantian-01');const rows=await fetchOperations('yantian-01');if(!disposed)records.value=rows}catch(e){if(!disposed)error.value=(e as Error).message}}
onMounted(()=>{refresh();timer=window.setInterval(refresh,30000)});onBeforeUnmount(()=>{disposed=true;window.clearInterval(timer)})
</script>
<template><div class="crop-center"><aside class="crop-sidebar"><a class="crop-brand" href="/platform/assistant"><AgentIcon name="leaf" :size="25"/><span>盐田丰语<small>农业智能工作空间</small></span></a><button class="back-agent" @click="router.push('/assistant')">← 返回智能问农</button><nav aria-label="作物中心分类"><button :class="{active:category==='all'}" @click="selectCrop('all')"><AgentIcon name="leaf" :size="19"/>作物总览<span>›</span></button><button v-for="c in categories" :key="c.id" :class="{active:category===c.id}" @click="selectCrop(c.id)"><span class="crop-icon" :style="{backgroundImage:`url(${cropImage})`,backgroundPosition:c.position}"/>{{c.name}}<span>›</span></button></nav><div class="sidebar-bottom"><button @click="router.push('/workspaces/farm-01')"><AgentIcon name="grid" :size="17"/>数据工作台 ↗</button><button @click="postharvest=true"><AgentIcon name="book" :size="17"/>采后管理 ↗</button><small>共享演示农场 · 每 30 秒更新</small></div></aside><main class="crop-main"><header class="crop-header"><div><small>农业决策工作空间</small><h1>作物中心</h1><p>观察生长 · 识别病虫害 · 管理农事 · 追溯收获</p></div><button @click="refresh">刷新数据 ↻</button></header><nav class="crop-tabs" aria-label="作物功能"><button v-for="t in tabs" :key="t.id" :aria-pressed="tab===t.id" :class="{active:tab===t.id}" @click="tab=t.id">{{t.name}}</button></nav><p v-if="error" role="alert" class="crop-error">{{error}}</p><div v-if="!snapshot" class="loading">正在读取作物档案…</div><template v-else><div class="crop-stats"><div><AgentIcon name="leaf" :size="24"/><span><strong>{{cards.filter(c=>c.zones.length).length}}<small>类</small></strong><em>作物种类</em></span></div><div><AgentIcon name="grid" :size="24"/><span><strong>{{snapshot.zones.length}}<small>块</small></strong><em>管理地块</em></span></div><div><AgentIcon name="book" :size="24"/><span><strong>{{records.filter(r=>r.kind==='BATCH').length}}<small>批</small></strong><em>已登记采收</em></span></div><div><AgentIcon name="check" :size="24"/><span><strong>{{snapshot.summary.health}}<small>分</small></strong><em>农场演示评分</em></span></div></div>
<Transition name="crop-content" mode="out-in"><section :key="tab+category" class="crop-content"><template v-if="tab==='overview'"><div class="overview-layout"><div><section class="crop-section"><div class="section-title"><h2>各作物种植情况</h2><span>{{category==='all'?'全部作物':activeCrop.name}}</span></div><div class="crop-card-grid"><article v-for="c in visible" :key="c.id" class="crop-card"><div class="crop-photo" role="img" :aria-label="c.name+'品种示意'" :style="{backgroundImage:`url(${cropImage})`,backgroundPosition:c.position}"><span>品种示意</span></div><div class="crop-card-copy"><h3>{{c.name}}<small>特色作物</small></h3><div class="crop-card-numbers"><span><strong>{{c.zones.length}}</strong><small>管理地块</small></span><span><strong>{{c.health??'—'}}<em v-if="c.health">分</em></strong><small>档案评分</small></span></div><dl><dt>采收登记</dt><dd>{{c.harvest}}</dd><dt>当前阶段</dt><dd>{{c.zones[0]?.stage||'暂无档案'}}</dd><dt>待处理告警</dt><dd :class="{warning:c.alerts}">{{c.alerts}} 条</dd></dl><button @click="selectCrop(c.id);tab='growth'">查看详情 →</button></div></article></div></section><section class="crop-section recent-tasks"><div class="section-title"><h2>近期农事与生长记录</h2><button @click="tab='agronomy'">管理记录 →</button></div><div class="task-grid"><article v-for="task in tasks" :key="task.id"><AgentIcon name="leaf" :size="20"/><div><strong>{{task.title}}</strong><small>{{names[task.entityId]}} · {{task.kind==='GROWTH'?'生长记录':'农事记录'}}</small><time>{{task.createdAt.slice(0,10)}}</time></div></article><p v-if="!tasks.length" class="hint">暂无记录，可在农事管理登记。</p></div></section></div><aside class="crop-insights"><section class="crop-section"><div class="section-title"><h2>作物档案评分分布</h2></div><div v-for="c in cards" :key="c.id" class="score-row"><span>{{c.name}}</span><div><i :style="{width:(c.health||0)+'%'}"/></div><b>{{c.health??'—'}}</b></div><p class="hint">当前档案评分，不作为病害概率。</p></section><section class="crop-section"><h2>观测异常与核验</h2><div class="alert-circle"><strong>{{riskCount}}</strong><span>待处理告警</span></div><p class="hint">结合环境与视觉记录核验，告警不代表病害确诊。</p><button class="crop-primary" @click="ask">交给 Agent 分析 ↗</button></section><section class="crop-section"><h2>农场环境趋势</h2><ObservationHistory :farm-id="snapshot.farmId" :updated-at="snapshot.generatedAt" :metrics="snapshot.environmentMetrics"/></section></aside></div></template>
<template v-else-if="tab==='growth'"><section class="crop-section"><div class="section-title"><h2>{{category==='all'?'全场':activeCrop.name}} · 生长监测</h2><button @click="ask">分析现有观测 ↗</button></div><div class="zone-grid"><article v-for="zone in snapshot.zones.filter(z=>category==='all'||cropKey(z.crop)===category)" :key="zone.entityId"><strong>{{names[zone.entityId]}}</strong><span>{{zone.crop}} · {{zone.area}}</span><p>{{zone.stage}}</p><small>{{zone.environment}}</small></article></div><h2>当前农场级环境</h2><div class="metric-grid"><article v-for="metric in snapshot.environmentMetrics" :key="metric.key"><span>{{metric.label}}</span><strong>{{metric.numericValue.toFixed(1)}}<small>{{metric.unit}}</small></strong></article></div><ObservationHistory :farm-id="snapshot.farmId" :updated-at="snapshot.generatedAt" :metrics="snapshot.environmentMetrics"/></section></template>
<template v-else-if="tab==='vision'"><section class="crop-section"><h2>病虫害识别</h2><CropVisionWorkbench embedded :farm-id="snapshot.farmId" :selected-id="activeCrop.zones[0]?.entityId||null" :plots="snapshot.zones" :names="names" @ask="router.push({path:'/assistant',query:{prompt:$event}})"/></section></template>
<template v-else-if="tab==='yield'"><section class="crop-section"><h2>产量与采收评估</h2><div class="zone-grid"><article v-for="c in visible" :key="c.id"><strong>{{c.name}}</strong><span>已登记采收量</span><p>{{c.harvest}}</p><small>{{c.batchCount}} 个采后批次</small></article></div><p class="hint">当前展示登记采收量；尚无校准的产量预测模型，不将登记量当作预计产量。</p><button class="crop-primary" @click="ask">分析产量评估所需资料 ↗</button><button class="crop-text-button" @click="postharvest=true">管理采收批次 →</button></section></template>
<template v-else><section class="crop-section"><h2>农事与生长档案</h2><OperationJournal kind="crops" :entity-id="category==='all'?undefined:activeCrop.zones[0]?.entityId"/></section></template></section></Transition><p class="crop-footer">盐田丰语 · 软件演示数据。图片为 AI 生成的作物品种示意。</p></template></main><PostHarvestCenter v-if="postharvest&&snapshot" :snapshot="snapshot" @close="postharvest=false" @ask="router.push({path:'/assistant',query:{prompt:$event}})"/></div></template>
<style scoped>
