imary{display:block;width:100%;border:0;border-radius:9px;background:var(--ui-brand);color:white;padding:11px;font-size:11px;margin-top:15px}.recent-tasks{margin-top:17px}.task-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:10px}.task-grid article{display:flex;align-items:flex-start;gap:10px;background:#f3f8f4;border-radius:10px;padding:13px;color:#71917c}.task-grid strong{display:block;font-size:11px;font-weight:500;overflow-wrap:anywhere}.task-grid small,.task-grid time{display:block;font-size:9px;color:#9ab0a2;margin-top:5px}.zone-grid,.metric-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin:18px 0 24px}.zone-grid article,.metric-grid article{padding:18px;border:1px solid var(--ui-brand-soft);border-radius:11px;background:#f7faf8}.zone-grid strong{display:block;font-size:13px;font-weight:550;color:var(--ui-brand)}.zone-grid span,.zone-grid small{display:block;font-size:10px;color:#91a798;margin-top:8px}.zone-grid p{font-size:12px;color:#769780}.metric-grid span{font-size:10px;color:#95aa9c}.metric-grid strong{display:block;font-size:25px;font-weight:550;color:var(--ui-brand);margin-top:9px}.metric-grid small{font-size:10px;margin-left:3px}.crop-model-entry{max-width:400px;margin:25px auto;text-align:center;color:#7d9988}.crop-model-entry .crop-photo{display:block;height:auto;aspect-ratio:1/1;border-radius:13px;background-size:200% 200%}.crop-model-entry h3{font-size:18px;font-weight:550}.crop-model-entry p{font-size:12px}.crop-model-entry small{display:block;font-size:10px;margin-top:12px}.crop-footer{font-size:9px;color:#a1b2a6;margin-top:22px}.loading{padding:70px;color:#95ac9d;text-align:center}.crop-error{padding:12px;background:#fff0e8;border-radius:9px;font-size:11px;color:#a57550}.crop-content-enter-active,.crop-content-leave-active{transition:opacity .2s,transform .2s}.crop-content-enter-from,.crop-content-leave-to{opacity:0;transform:translateY(7px)}@media(min-width:1700px){.crop-card-grid{grid-template-columns:repeat(4,1f