</style>
<style scoped>.crop-card>.crop-photo{width:min(100%,240px);margin:12px auto 0;border-radius:10px}.crop-model-entry .crop-photo{width:min(100%,300px);margin:auto}@media(max-width:700px){.crop-card>.crop-photo{width:min(100%,220px)}}</style>
